Customer/Broker Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Customer/Broker Portal container

Container_Boundary(customer_broker_portal, "Customer/Broker Portal") {
    Component(Customer_Broker_UI, "Customer/Broker UI", "React", "Public Single Page Application (SPA) providing the user interface for end customers and brokers to submit and view claims.")
    Component(Customer_Broker_BFF_API, "Customer/Broker BFF API", "ASP.NET Core", "Backend-For-Frontend API handling security controls, session management, and native Azure integration for the portal UI.")
}

Rel(Customer_Broker_UI, Customer_Broker_BFF_API, "Sends API requests", "HTTPS")

@enduml

Adjuster Workstation.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(adjuster_workstation, "Adjuster Workstation") {
    Component(adjuster_ui_controller, "Adjuster UI Controller", "Angular, Azure App Service", "Renders the internal UI optimized for sub-2s loads and handles user interactions for claims adjusters and managers.")
    Component(adjuster_session_auth_handler, "Adjuster Session & Auth Handler", "OAuth 2.0 / OIDC, Azure App Service", "Manages authentication and secure session tokens for claims adjusters communicating via Corporate Active Directory / Azure AD.")
    Component(local_read_model_cache, "Local Read-Model Cache", "Azure SQL Database", "Provides fast local caching of claim data to ensure sub-2s UI response times for the adjuster workstation.")
}

Rel(adjuster_ui_controller, local_read_model_cache, "Queries cached claim data for rapid UI rendering", "HTTPS")
Rel(adjuster_ui_controller, adjuster_session_auth_handler, "Authenticates user session", "OAuth 2.0 / OIDC")

@enduml

Integration & Routing Engine.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("integration_routing_engine", "Integration & Routing Engine") {
    Component(Claim_Router_Component, "Claim Router Component", ".NET Isolated Azure Functions", "Routes claim submissions using Azure Functions.")
    Component(Deduplication_State_Component, "Deduplication & State Component", "Azure Cosmos DB", "Enforces idempotency and tracks state for deduplication.")
    Component(Fallback_Switch_Component, "Fallback Switch Component", "Azure App Configuration", "Dynamically manages routing rules for the 1-day mainframe fallback.")
    Component(Retry_DLQ_Handler_Component, "Retry & DLQ Handler Component", ".NET Azure Functions", "Manages asynchronous queuing, AMQP delivery, and Dead-Letter Queues.")
}

Rel(Claim_Router_Component, Deduplication_State_Component, "Checks state and enforces idempotency", "")
Rel(Claim_Router_Component, Fallback_Switch_Component, "Evaluates fallback routing rules", "")
Rel(Retry_DLQ_Handler_Component, Claim_Router_Component, "Retries failed claim routing", "")

@enduml

